param([Parameter(Mandatory=$true)][string]$GameRoot,[string]$Output=(Join-Path $PSScriptRoot '../../docs/research/rimworld/evidence/armor-xml.json'))
$ErrorActionPreference='Stop'
$assembly=(Get-FileHash -LiteralPath (Join-Path $GameRoot 'Assembly-CSharp.dll') -Algorithm SHA256).Hash.ToLowerInvariant()
if($assembly -ne 'eff7d97949f919fb2b151ebfb906e9be749b63410b7dbda78eeebb7972b245c3'){throw 'Review changed assembly before updating armor evidence.'}
$garment=@('thingClass','category','useHitPoints','statBases','recipeMaker','costStuffCount','costList','stuffCategories','damageMultipliers','comps','equippedStatOffsets','apparel/bodyPartGroups','apparel/layers','apparel/wearPerDay','apparel/useDeflectMetalEffect')
$stat=@('defaultBaseValue','minValue','maxValue','workerClass','parts','statFactors','skillNeedFactors','capacityFactors','roundValue','roundToFiveOver')
$bench=@('statBases','costStuffCount','costList','stuffCategories','researchPrerequisites','constructionSkillPrerequisite','size','interactionCellOffset','building','comps')
$selections=@(
 @('garment','Data/Core/Defs/ThingDefs_Misc/Apparel_Various.xml',"/Defs/ThingDef[@Name='ApparelNoQualityBase' or @Name='ApparelBase' or @Name='ApparelMakeableBase' or @Name='ArmorSmithableBase' or @Name='ArmorMachineableBase' or defName='Apparel_PlateArmor' or defName='Apparel_Parka' or defName='Apparel_Duster' or defName='Apparel_BasicShirt' or defName='Apparel_CollarShirt' or defName='Apparel_Pants']",$garment),
 @('garment','Data/Core/Defs/ThingDefs_Misc/Apparel_Headgear.xml',"/Defs/ThingDef[@Name='HatMakeableBase' or @Name='ArmorHelmetMakeableBase' or defName='Apparel_Tuque' or defName='Apparel_SimpleHelmet']",$garment),
 @('stat','Data/Core/Defs/Stats/Stats_Apparel.xml',"/Defs/StatDef[@Name='ArmorRatingBase' or @Name='InsulationBase' or defName='ArmorRating_Sharp' or defName='ArmorRating_Blunt' or defName='ArmorRating_Heat' or defName='StuffEffectMultiplierArmor' or defName='Insulation_Cold' or defName='Insulation_Heat' or defName='StuffEffectMultiplierInsulation_Cold' or defName='StuffEffectMultiplierInsulation_Heat']",$stat),
 @('stat','Data/Core/Defs/Stats/Stats_Basics_General.xml',"/Defs/StatDef[defName='MaxHitPoints' or defName='WorkToMake']",$stat),
 @('stat','Data/Core/Defs/Stats/Stats_Weapons_Melee.xml',"/Defs/StatDef[defName='MeleeWeapon_DamageMultiplier']",$stat),
 @('stat','Data/Core/Defs/Stats/Stats_Weapons_Ranged.xml',"/Defs/StatDef[defName='RangedWeapon_DamageMultiplier' or defName='RangedWeapon_ArmorPenetrationMultiplier']",$stat),
 @('stat','Data/Core/Defs/Stats/Stats_Pawns_General.xml',"/Defs/StatDef[defName='MoveSpeed']",$stat),
 @('stuff','Data/Core/Defs/ThingDefs_Items/Items_Resource_Stuff.xml',"/Defs/ThingDef[defName='Steel' or defName='Cloth' or defName='WoodLog']",@('statBases','stuffProps/statFactors','stuffProps/statOffsets','stuffProps/statFactorsQuality','stuffProps/statOffsetsQuality','stuffProps/categories','damageMultipliers')),
 @('layer','Data/Core/Defs/Misc/ApparelLayerDefs/ApparelLayerDefs.xml',"/Defs/ApparelLayerDef[defName='OnSkin' or defName='Middle' or defName='Shell' or defName='Overhead']",@('drawOrder')),
 @('category','Data/Core/Defs/Misc/DamageArmorCategoryDef/DamageArmorCategoryDefs.xml','/Defs/DamageArmorCategoryDef',@('armorRatingStat','multStat')),
 @('human','Data/Core/Defs/ThingDefs_Races/Races_Humanlike.xml',"/Defs/ThingDef[defName='Human']",@('statBases','tools','damageMultipliers')),
 @('human','Data/Core/Defs/ThingDefs_Races/Races_Animal_Base.xml',"/Defs/ThingDef[@Name='BasePawn']",@('statBases','damageMultipliers')),
 @('research','Data/Core/Defs/ResearchProjectDefs/ResearchProjects_1.xml',"/Defs/ResearchProjectDef[defName='Smithing' or defName='PlateArmor' or defName='ComplexClothing']",@('baseCost','techLevel','prerequisites')),
 @('bench','Data/Core/Defs/ThingDefs_Buildings/Buildings_Production.xml',"/Defs/ThingDef[@Name='BenchBase' or defName='FueledSmithy' or defName='ElectricSmithy' or defName='TableMachining']",$bench),
 @('weapon','Data/Core/Defs/ThingDefs_Misc/Weapons/MeleeNeolithic.xml',"/Defs/ThingDef[defName='MeleeWeapon_Club' or defName='MeleeWeapon_Knife']",@('tools')),
 @('weapon','Data/Core/Defs/ThingDefs_Misc/Weapons/MeleeMedieval.xml',"/Defs/ThingDef[defName='MeleeWeapon_LongSword']",@('tools')),
 @('damage','Data/Core/Defs/DamageDefs/Damages_MeleeWeapon.xml',"/Defs/DamageDef[defName='Cut' or defName='Stab' or defName='Blunt' or defName='Poke' or defName='Bite']",@('workerClass','hediff','hediffSkin','hediffSolid','armorCategory','harmsHealth','externalViolence','buildingDamageFactor','plantDamageFactor','corpseDamageFactor'))
)
function Relative-XPath($leaf,$root){$parts=[Collections.Generic.List[string]]::new();$cursor=$leaf;while($cursor -ne $root){$tag=$cursor.LocalName;$siblings=@($cursor.ParentNode.ChildNodes|Where-Object{$_.NodeType -eq 'Element' -and $_.LocalName -eq $tag});$segment=$tag;if($siblings.Count -gt 1){$segment+='['+([Array]::IndexOf($siblings,$cursor)+1)+']'};$parts.Insert(0,$segment);$cursor=$cursor.ParentNode};return ($parts -join '/')}
$records=[Collections.Generic.List[object]]::new()
foreach($s in $selections){$file=Join-Path $GameRoot $s[1];[xml]$doc=Get-Content -Raw -LiteralPath $file;$sha=(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant();$nodes=$doc.SelectNodes($s[2]);if(!$nodes.Count){throw "No nodes: $($s[2])"}
 foreach($node in $nodes){$def=$node.SelectSingleNode('defName');$name=if($def){$def.InnerText}else{$node.GetAttribute('Name')};$xp='/Defs/'+$node.LocalName+$(if($def){"[defName='$name']"}else{"[@Name='$name']"});$leaves=[Collections.Generic.List[object]]::new();$attrs=[Collections.Generic.List[object]]::new();$absent=[Collections.Generic.List[string]]::new()
  foreach($selector in $s[3]){$chosen=$node.SelectNodes($selector);if(!$chosen.Count){$absent.Add($selector);continue};foreach($top in $chosen){$scan=@($top)+@($top.SelectNodes('.//*'));foreach($child in $scan){$rel=Relative-XPath $child $node;if($rel -match '/(label|description)$'){continue};if($child.Attributes.Count){$a=[ordered]@{};foreach($item in $child.Attributes){$a[$item.Name]=$item.Value};$attrs.Add([ordered]@{xpath=$xp+'/'+$rel;attributes=$a})};if(!$child.SelectNodes('*').Count){$leaves.Add([ordered]@{xpath=$xp+'/'+$rel;value=$child.InnerText})}}}}
  $records.Add([ordered]@{group=$s[0];id=$node.LocalName+'_'+$name;def_name=$name;parent_name=$node.GetAttribute('ParentName');name_attribute=$node.GetAttribute('Name');source=[ordered]@{path=$s[1];xpath=$xp;sha256=$sha};selected_paths=$s[3];absent_paths=@($absent.ToArray());fields=@($leaves.ToArray());node_attributes=@($attrs.ToArray())})
 }
}
$result=[ordered]@{evidence_id='RW17-ARMOR-XML';version_text=(Get-Content -Raw -LiteralPath (Join-Path $GameRoot 'Version.txt')).Trim();assembly_sha256=$assembly;kind='Selected direct Core armor, clothing, material, quality, coverage, weapon penetration and crafting declarations';limitations=@('Reviewed selected inheritance chains; not the enabled-mod effective database.','Source omissions are retained, not silently interpreted as effective values.','Static extraction does not execute original gameplay or project implementation.');records=@($records.ToArray())}
[IO.File]::WriteAllText([IO.Path]::GetFullPath($Output),(($result|ConvertTo-Json -Depth 32) -replace "`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false));Write-Output "Recorded $($records.Count) selected armor XML records."
